{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 위원회 위촉직 중 청년 최소 비율 기준",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장은 시의 각종 위원회를 구성할 때 위촉직 위원의 10분의 1 이상을 청년으로 위촉하여야 한다. 여기서 청년은 19세 이상 39세 이하의 사람을 말한다.",
          "b_ids": "청년:제10조제4항, 청년:제3조제1호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "청년정책을 주로 다루는 위원회의 청년 위촉직 비율 기준 차이",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "청년정책을 주로 다루는 위원회의 경우 위촉직 위원의 10분의 3 이상을 청년으로 위촉하여야 하므로, 일반 위원회(10분의 1 이상)보다 기준이 높아진다.",
          "b_ids": "청년:제10조제4항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
